def apply(path, reps):
    s = open(path, encoding='utf-8').read()
    for a, b in reps:
        n = s.count(a)
        if n != 1:
            sys.stderr.write(u'⛔ %s: якорь встречается %d раз: %r\n' % (path, n, a[:80]))
